class Batch:
    def __init__(self, item_id, batch_id, size=''):
        self.item_id, self.batch_id = self._norm_ids(item_id, batch_id)
        self.size = _size(size) if size is not None else None

    @staticmethod
    def _norm_ids(item_id, batch_id):
        item, batch = int(item_id), int(batch_id)
        if not (0 <= item <= 9999 and 0 <= batch <= 99):
            raise ValueError('item or batch ID out of range')
        return f'{item:04d}', f'{batch:02d}'

    @classmethod
    def get_relpath(cls, item_id, batch_id, size='', ext='zip'):
        item, batch = cls._norm_ids(item_id, batch_id)
        prefix = f'{_size(size)}_' if size else ''
        return os.path.join('items', f'{prefix}covers_{item}',
                            f'{prefix}covers_{item}_{batch}.{ext.lstrip(\".\")}')

    @classmethod
    def get_abspath(cls, item_id, batch_id, size='', ext='zip'):
        return os.path.join(config.data_root, cls.get_relpath(item_id, batch_id, size, ext))

    @property
    def start_id(self):
        return int(self.item_id) * 1_000_000 + int(self.batch_id) * BATCH_SIZE

    @contextlib.contextmanager
    def lock(self):
        # A stable lock file covers packaging, upload checks, and finalization.
        path = self.get_abspath(self.item_id, self.batch_id, ext='lock')
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, 'a+b') as lockfile:
            fcntl.flock(lockfile, fcntl.LOCK_EX)
            try:
                yield
            finally:
                fcntl.flock(lockfile, fcntl.LOCK_UN)

    def process_pending(self, upload=False, finalize=False, test=False, uploader=None):
        uploader = uploader or Uploader()
        sizes = SIZES if self.size is None or self.size == '' else (self.size,)
        with self.lock():
            paths = [self.get_abspath(self.item_id, self.batch_id, size) for size in sizes]
            paths = [path for path in paths if os.path.isfile(path)]
            if not paths:
                return False
            if upload and not test:
                for path in paths:
                    item = os.path.basename(os.path.dirname(path))
                    if not uploader.is_uploaded(item, os.path.basename(path)):
                        uploader.upload(item, [path])
            if not finalize:
                return True
            # A cover is complete only when all four archives exist remotely.
            expected = [self.get_abspath(self.item_id, self.batch_id, size) for size in SIZES]
            if not all(os.path.isfile(path) and uploader.is_uploaded(
                    os.path.basename(os.path.dirname(path)), os.path.basename(path))
                    for path in expected):
                return False
            if not test:
                self.finalize(test=False)
            return True

    def finalize(self, start_id=None, test=False):
        if start_id is not None and int(start_id) "'!= self.start_id:
            raise ValueError('"'start ID does not match batch')
        if test:
            return
        CoverDB.update_completed_batch(self.item_id, self.batch_id)
        # Local originals remain until the database points at verified uploads.
        coverdb = CoverDB()
        for row in coverdb.completed_batch(self.start_id):
            cover = Cover(row)
            for size in SIZES:
                field = 'filename' + (f'_{size}' if size else '')
                # Completed rows now contain remote URLs; old local names are
                # recorded by update_completed_batch for this cleanup instead.
                old = getattr(cover, field, None)
                if old and not old.startswith(('http://', 'https://')):
                    path = os.path.join(config.data_root, 'localdisk', old)
                    if os.path.isfile(path):
                        os.remove(path)


class ZipManager:
    def __init__(self):
        self.zips = {}

    def get_zipfile(self, name):
        cover_id = int(name[:10])
        size = name[11].lower() if len(name) > 11 and name[10] == '-' else ''
        item, batch = Cover.id_to_item_and_batch_id(cover_id)
        path = Batch.get_abspath(item, batch, size)
        if path not in self.zips:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            archive = zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED,
                                      allowZip64=True)
            self.zips[path] = (archive, set(archive.namelist()))
        return self.zips[path]

    def add_file(self, name, filepath, mtime):
        archive, names = self.get_zipfile(name)
        if name not in names:
            info = zipfile.ZipInfo(name, time.localtime(mtime)[:6])
            info.compress_type = zipfile.ZIP_STORED
            with open(filepath, 'rb') as source, archive.open(info, 'w') as target:
                while chunk := source.read(1024 * 1024):
                    target.write(chunk)
            names.add(name)
        return archive.filename

    def close(self):
        for archive, _ in self.zips.values():
            archive.close()
        self.zips.clear()


def count_files_in_zip(filepath):
    with zipfile.ZipFile(filepath) as archive:
        return sum(name.lower().endswith('.jpg') for name in archive.namelist())


def open_zipfile(name):
    manager = ZipManager()
    archive, _ = manager.get_zipfile(name)
    return archive


def get_zipfile(name):
    return open_zipfile(name)


class Uploader:
    @staticmethod
    def upload(itemname, filepaths):
        return subprocess.run(['ia', 'upload', itemname, *filepaths, '--retries', '10'],
                              check=True, capture_output=True, text=True)

    @staticmethod
    def is_uploaded(item, zip_filename, verbose=False):
        result = subprocess.run(['ia', 'list', item], check=True, capture_output=True, text=True)
        found = zip_filename in {line.strip().split('\\t')[0] for line in result.stdout.splitlines()}
        if verbose:
